INSERT INTO _migration_434_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_membranes_s1_001', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the fluid mosaic model of the cell surface membrane, what does the word ''mosaic'' describe?', 'multiple_choice', NULL, '["A. Phospholipids arranged in a single layer","B. Protein molecules scattered within the phospholipid bilayer","C. Cholesterol molecules forming a rigid frame","D. Carbohydrate chains covering the entire outer surface"]', 'B', 'The mosaic is the patchwork of intrinsic and extrinsic proteins embedded in, or attached to, the fluid phospholipid bilayer. Phospholipids form a bilayer rather than a single layer, cholesterol modulates fluidity rather than forming a frame, and carbohydrate chains occur only on some proteins and lipids. Therefore the correct answer is B: Protein molecules scattered within the phospholipid bilayer.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s1_002', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Facilitated diffusion differs from simple diffusion across a membrane because facilitated diffusion requires...', 'multiple_choice', NULL, '["A. ATP hydrolysed by carrier proteins","B. vesicles formed from the membrane","C. transport proteins such as channel or carrier proteins","D. movement of molecules against their gradient"]', 'C', 'Facilitated diffusion moves polar molecules or ions down their concentration gradient through specific channel or carrier proteins; it is passive, so no ATP is needed. Vesicles mediate endocytosis, and moving substances against their gradient is active transport. Therefore the correct answer is C: transport proteins such as channel or carrier proteins.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s1_003', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A red blood cell is placed in a solution with a lower (more negative) water potential than the cell''s cytoplasm. Which outcome is most likely?', 'multiple_choice', NULL, '["A. Water enters the cell and it bursts (haemolysis)","B. Water enters by active transport and the cell swells","C. No water movement occurs because the membrane is impermeable to water","D. Water leaves the cell by osmosis and the cell shrinks (crenation)"]', 'D', 'Water moves from the higher water potential inside the cell to the lower water potential outside, across the partially permeable membrane by osmosis. Red blood cells have no cell wall, so the loss of water makes them shrink and develop a spiky, crenated appearance. Therefore the correct answer is D: Water leaves the cell by osmosis and the cell shrinks (crenation).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s1_004', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which process requires both a carrier protein and a supply of ATP?', 'multiple_choice', NULL, '["A. Active transport of mineral ions into root hair cells","B. Facilitated diffusion of glucose into a red blood cell","C. Osmosis of water into a plant cell","D. Simple diffusion of oxygen into an alveolar cell"]', 'A', 'Active transport moves substances against their concentration (electrochemical) gradient using carrier proteins powered by ATP, as when root hair cells absorb mineral ions from very dilute soil water. Facilitated diffusion and osmosis follow gradients and need no ATP, and oxygen crosses membranes by simple diffusion. Therefore the correct answer is A: Active transport of mineral ions into root hair cells.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s1_005', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'The sodium–potassium pump moves three Na⁺ ions out of a neurone and two K⁺ ions in for each ATP hydrolysed. What is the direct consequence of this stoichiometry?', 'multiple_choice', NULL, '["A. The membrane potential across the membrane is abolished","B. The inside of the cell becomes more negative relative to the outside (the pump is electrogenic)","C. Equal numbers of positive charges move in each direction","D. Sodium ions diffuse back into the cell through the pump"]', 'B', 'Each cycle of the pump moves a net one positive charge out of the cell (three Na⁺ out versus two K⁺ in), so the pump directly makes the inside more negative and contributes to the resting potential. The stoichiometry is fixed at 3:2, and the pump does not allow sodium to diffuse back through it. Therefore the correct answer is B: The inside of the cell becomes more negative relative to the outside (the pump is electrogenic).', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_membranes_s1_006', 'topic_alevel_bio_membranes', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student investigates how substances cross cell surface membranes.', 'structured', NULL, NULL, '(a) Osmosis is the net movement of water molecules from a region of higher (less negative) water potential to a region of lower (more negative) water potential across a partially permeable membrane, down the water potential gradient. (b) Active transport moves substances against their concentration (electrochemical) gradient. Carrier proteins must change shape to move the substance across the membrane, and this shape change is driven by energy released when ATP is hydrolysed to ADP and inorganic phosphate. (c) Cholesterol sits between the phospholipid molecules and, at low temperatures, prevents the phospholipid tails packing too closely together, maintaining fluidity; it therefore buffers the membrane against temperature change and helps stabilise it.', '(a) Osmosis is the net movement of water molecules from a region of higher (less negative) water potential to a region of lower (more negative) water potential across a partially permeable membrane, down the water potential gradient. (b) Active transport moves substances against their concentration (electrochemical) gradient. Carrier proteins must change shape to move the substance across the membrane, and this shape change is driven by energy released when ATP is hydrolysed to ADP and inorganic phosphate. (c) Cholesterol sits between the phospholipid molecules and, at low temperatures, prevents the phospholipid tails packing too closely together, maintaining fluidity; it therefore buffers the membrane against temperature change and helps stabilise it.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_434_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_membranes_s1_006_a', 'q_albio_membranes_s1_006', 'a', 'Define the term osmosis.', '2', 'Osmosis is the net movement of water molecules from a region of higher (less negative) water potential to a region of lower (more negative) water potential across a partially permeable membrane, down the water potential gradient.', '1'),
('sqp_q_albio_membranes_s1_006_b', 'q_albio_membranes_s1_006', 'b', 'Explain why active transport requires a supply of ATP.', '2', 'Active transport moves substances against their concentration (electrochemical) gradient. Carrier proteins must change shape to move the substance across the membrane, and this shape change is driven by energy released when ATP is hydrolysed to ADP and inorganic phosphate.', '2'),
('sqp_q_albio_membranes_s1_006_c', 'q_albio_membranes_s1_006', 'c', 'Describe the role of cholesterol in the cell surface membrane when the temperature falls.', '2', 'Cholesterol sits between the phospholipid molecules and, at low temperatures, prevents the phospholipid tails packing too closely together, maintaining fluidity; it therefore buffers the membrane against temperature change and helps stabilise it.', '3');
INSERT INTO _migration_434_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_434_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_434_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_434_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_434_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_434_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_434_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_434_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_434_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_434_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_434_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_434_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
